package dev.gbppimentel.zzz;
import android.app.usage.*;import android.content.*;import org.json.*;
public final class UsageTimeProbe {public static void main(String[] args)throws Exception{try{if(android.os.Looper.getMainLooper()==null)android.os.Looper.prepareMainLooper();Object thread=Class.forName("android.app.ActivityThread").getMethod("systemMain").invoke(null);Context c=(Context)thread.getClass().getMethod("getSystemContext").invoke(thread);UsageStatsManager u=c.getSystemService(UsageStatsManager.class);long total=0;int n=0;for(UsageStats s:u.queryUsageStats(UsageStatsManager.INTERVAL_YEARLY,0,System.currentTimeMillis()))if(s.getPackageName().equals("com.HoYoverse.Nap")){total+=s.getTotalTimeInForeground();n++;java.lang.reflect.Field field=s.getClass().getField("mActivities");System.out.println("active="+field.get(s)+" lastUsed="+s.getLastTimeUsed()+" now="+System.currentTimeMillis());}System.out.println(new JSONObject().put("buckets",n).put("foregroundMs",total));}catch(Throwable t){System.out.println(t.toString()+" cause="+t.getCause());}}}
